import { Hono } from 'hono';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { z } from 'zod';

const router = new Hono();
import { prisma } from '../lib/prisma';
const JWT_SECRET = process.env.JWT_SECRET || 'fallback-secret-for-dev-only';
const JWT_REFRESH_SECRET = process.env.JWT_REFRESH_SECRET || 'fallback-refresh-secret-for-dev-only';

const authLimiter = async (c: any, next: any) => { await next(); };
const registerSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  name: z.string().min(2),
});

const loginSchema = z.object({
  email: z.string().email(),
  password: z.string(),
});

// POST /api/auth/register
router.post('/register', authLimiter, async (c) => {
  try {
    const validated = registerSchema.parse(req.body);
    const { email, password, name } = validated;
    
    // Check if user exists
    const existingUser = await prisma.user.findUnique({ where: { email } });
    if (existingUser) {
      return c.json({ error: 'User already exists' }, 400);
    }

    const hashedPassword = await bcrypt.hash(password, 10);
    const user = await prisma.user.create({
      data: {
        email,
        name,
        password: hashedPassword,
        // Role defaults to CUSTOMER as per schema
      },
    });

    const accessToken = jwt.sign({ userId: user.id, role: user.role }, JWT_SECRET, { expiresIn: '15m' });
    const refreshToken = jwt.sign({ userId: user.id, role: user.role }, JWT_REFRESH_SECRET, { expiresIn: '7d' });
    
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000,
    });
    
    return c.json({ accessToken, user: { id: user.id, email: user.email, name: user.name, role: user.role } }, 201);
  } catch (error: any) {
    console.error(error);
    if (error instanceof z.ZodError) {
      return c.json({ error: error.errors }, 400);
    }
    return c.json({ error: 'Internal server error' }, 500);
  }
});

// POST /api/auth/login
router.post('/login', authLimiter, async (c) => {
  try {
    const validated = loginSchema.parse(req.body);
    const { email, password } = validated;
    
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !user.password) {
      return c.json({ error: 'Invalid credentials' }, 400);
    }

    const isValid = await bcrypt.compare(password, user.password);
    if (!isValid) {
      return c.json({ error: 'Invalid credentials' }, 400);
    }

    const accessToken = jwt.sign({ userId: user.id, role: user.role }, JWT_SECRET, { expiresIn: '15m' });
    const refreshToken = jwt.sign({ userId: user.id, role: user.role }, JWT_REFRESH_SECRET, { expiresIn: '7d' });
    
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000,
    });
    
    return c.json({ accessToken, user: { id: user.id, email: user.email, name: user.name, role: user.role } });
  } catch (error: any) {
    console.error(error);
    if (error instanceof z.ZodError) {
      return c.json({ error: error.errors }, 400);
    }
    return c.json({ error: 'Internal server error' }, 500);
  }
});

// POST /api/auth/refresh
router.post('/refresh', async (c) => {
  try {
    const refreshToken = req.cookies?.refreshToken;
    if (!refreshToken) {
      return c.json({ error: 'No refresh token provided' }, 401);
    }

    const decoded = jwt.verify(refreshToken, JWT_REFRESH_SECRET) as any;
    const accessToken = jwt.sign({ userId: decoded.userId, role: decoded.role }, JWT_SECRET, { expiresIn: '15m' });
    
    return c.json({ accessToken });
  } catch (error) {
    return c.json({ error: 'Invalid or expired refresh token' }, 401);
  }
});

// POST /api/auth/logout
router.post('/logout', (c) => {
  res.clearCookie('refreshToken');
  return c.json({ message: 'Logged out successfully' });
});

export default router;
