import { Hono } from 'hono';
import { verifyToken, requireRoles } from '../middleware/auth';
import { createShiprocketOrder } from '../lib/shiprocket';

const router = new Hono();
import { prisma } from '../lib/prisma';

router.post('/create', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'ORDER_FULFILLMENT']), async (c) => {
  try {
    const body = await c.req.json();
    const { orderId } = body;

    // Fetch order from DB
    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: { orderItems: true }
    });

    if (!order) return c.json({ error: 'Order not found' }, 404);

    // Format payload for Shiprocket
    const shiprocketPayload = {
      order_id: order.id,
      order_date: order.createdAt.toISOString().slice(0, 10),
      pickup_location: "Primary",
      billing_customer_name: "Customer", // This would come from a proper address model in a full app
      billing_last_name: "",
      billing_address: "Address Line 1",
      billing_city: "City",
      billing_pincode: "110001",
      billing_state: "State",
      billing_country: "India",
      billing_email: "customer@example.com",
      billing_phone: "9999999999",
      shipping_is_billing: true,
      order_items: order.orderItems.map(item => ({
        name: `Product ${item.productId}`, // Simplified for now
        sku: `SKU-${item.variantId || item.productId}`,
        units: item.quantity,
        selling_price: item.price,
      })),
      payment_method: order.paymentStatus === 'PAID' ? 'Prepaid' : 'COD',
      sub_total: order.totalAmount,
      length: 10,
      breadth: 10,
      height: 10,
      weight: 0.5
    };

    const shiprocketResponse = await createShiprocketOrder(shiprocketPayload);

    // Update internal order with Shiprocket Order ID and AWB (if generated)
    await prisma.order.update({
      where: { id: order.id },
      data: {
        shippingStatus: 'PROCESSING',
        // In a real app, store shiprocketResponse.order_id and shiprocketResponse.awb_code
      }
    });

    return c.json({ success: true, shiprocketResponse });
  } catch (error: any) {
    console.error('Shipping Error:', error.response?.data || error);
    return c.json({ error: 'Failed to push order to shipping provider' }, 500);
  }
});

export default router;
