import { Hono } from 'hono';
import { verifyToken, requireRoles } from '../middleware/auth';

const router = new Hono();
import { prisma } from '../lib/prisma';

// GET all categories
router.get('/', async (c) => {
  try {
    const categories = await prisma.category.findMany({
      include: { children: true },
    });
    return c.json(categories);
  } catch (error) {
    return c.json({ error: 'Failed to fetch categories' }, 500);
  }
});

// POST new category (Admin only)
router.post('/', verifyToken, requireRoles(['SUPER_ADMIN', 'CATALOG_MANAGER']), async (c) => {
  try {
    const body = await c.req.json();
    const { name, slug, description, parentId } = body;
    const category = await prisma.category.create({
      data: { name, slug, description, parentId },
    });
    return c.json(category, 201);
  } catch (error) {
    return c.json({ error: 'Failed to create category' }, 500);
  }
});

// PUT update category (Admin only)
router.put('/:id', verifyToken, requireRoles(['SUPER_ADMIN', 'CATALOG_MANAGER']), async (c) => {
  try {
    const { id } = c.req.param();
    const body = await c.req.json();
    const { name, slug, description, parentId } = body;
    const category = await prisma.category.update({
      where: { id },
      data: { name, slug, description, parentId },
    });
    return c.json(category);
  } catch (error) {
    return c.json({ error: 'Failed to update category' }, 500);
  }
});

// DELETE category (Admin only)
router.delete('/:id', verifyToken, requireRoles(['SUPER_ADMIN', 'CATALOG_MANAGER']), async (c) => {
  try {
    const { id } = c.req.param();
    await prisma.category.delete({ where: { id } });
    return c.body(null, 204);
  } catch (error) {
    return c.json({ error: 'Failed to delete category' }, 500);
  }
});

export default router;
