import { Hono } from 'hono';
import { verifyToken, requireRoles } from '../middleware/auth';

const router = new Hono();
import { prisma } from '../lib/prisma';

// POST new order (Checkout)
router.post('/', async (c) => {
  try {
    const body = await c.req.json();
    const { userId, items, address, totalAmount } = body;
    
    // In a real scenario, we'd calculate totalAmount securely here by fetching variant prices from DB
    // rather than trusting the client's totalAmount.

    // Using Prisma Transaction for safety
    const result = await prisma.$transaction(async (tx) => {
      
      // 1. Verify and deduct stock for each item
      for (const item of items) {
        const variant = await tx.variant.findUnique({
          where: { id: item.variantId },
          include: { product: true }
        });
        
        if (!variant) throw new Error(`Variant not found: ${item.variantId}`);
        
        // If not made to order, ensure stock is sufficient and deduct
        if (!variant.product.isMadeToOrder) {
          if (variant.stock < item.quantity) {
            throw new Error(`Insufficient stock for ${variant.product.name}`);
          }
          
          await tx.variant.update({
            where: { id: item.variantId },
            data: { stock: { decrement: item.quantity } }
          });
        }
      }

      // 2. Create the Order
      const order = await tx.order.create({
        data: {
          userId: userId || undefined, // undefined for guest checkout if schema allows (our schema currently requires user, so we'd need to adjust or create guest users)
          totalAmount,
          status: 'PENDING',
          items: {
            create: items.map((item: any) => ({
              variantId: item.variantId,
              quantity: item.quantity,
              price: item.price,
              customization: item.customization || null
            }))
          },
          // Mock Payment creation
          payment: {
            create: {
              gateway: 'MOCK_RAZORPAY',
              transactionId: `txn_${Date.now()}`,
              status: 'SUCCESS',
              amount: totalAmount
            }
          }
        },
        include: { items: true, payment: true }
      });
      
      return order;
    });

    return c.json(result, 201);
  } catch (error: any) {
    console.error("Order creation failed:", error.message);
    return c.json({ error: error.message || 'Failed to create order' }, 400);
  }
});

// GET all orders (Admin)
router.get('/', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'ORDER_FULFILLMENT', 'CUSTOMER_SUPPORT', 'FINANCE']), async (c) => {
  try {
    const orders = await prisma.order.findMany({
      include: {
        user: { select: { name: true, email: true } },
        payment: true
      },
      orderBy: { createdAt: 'desc' }
    });
    return c.json(orders);
  } catch (error) {
    return c.json({ error: 'Failed to fetch orders' }, 500);
  }
});

// PUT update order status (Admin)
router.put('/:id/status', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'ORDER_FULFILLMENT']), async (c) => {
  try {
    const { id } = c.req.param();
    const body = await c.req.json();
    const { status, note } = body;
    
    const order = await prisma.order.update({
      where: { id },
      data: { status }
    });

    // Create a timeline log for this status change
    await prisma.orderTimeline.create({
      data: {
        orderId: id,
        status,
        note: note || `Status changed to ${status}`,
        userId: c.get('user').userId
      }
    });
    
    return c.json(order);
  } catch (error) {
    return c.json({ error: 'Failed to update order status' }, 500);
  }
});

// PUT update internal notes
router.put('/:id/notes', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'ORDER_FULFILLMENT']), async (c) => {
  try {
    const { id } = c.req.param();
    const body = await c.req.json();
    const { internalNotes } = body;
    
    const order = await prisma.order.update({
      where: { id },
      data: { internalNotes }
    });
    
    return c.json(order);
  } catch (error) {
    return c.json({ error: 'Failed to update internal notes' }, 500);
  }
});

// GET order timeline
router.get('/:id/timeline', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'ORDER_FULFILLMENT', 'CUSTOMER_SUPPORT']), async (c) => {
  try {
    const { id } = c.req.param();
    const timeline = await prisma.orderTimeline.findMany({
      where: { orderId: id },
      include: { user: { select: { name: true, role: true } } },
      orderBy: { createdAt: 'desc' }
    });
    return c.json(timeline);
  } catch (error) {
    return c.json({ error: 'Failed to fetch timeline' }, 500);
  }
});

import { ShippingService } from '../services/shipping';

// POST fulfill order (Generate Label) (Admin only)
router.post('/:id/fulfill', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'ORDER_FULFILLMENT']), async (c) => {
  try {
    const { id } = c.req.param();
    
    // Check if order exists and is not already shipped
    const order = await prisma.order.findUnique({ where: { id }, include: { shipment: true } });
    if (!order) return c.json({ error: 'Order not found' }, 404);
    if (order.shipment) return c.json({ error: 'Order already has a shipment' }, 400);
    
    const shipment = await ShippingService.generateLabel(id);
    
    return c.json(shipment);
  } catch (error) {
    return c.json({ error: 'Failed to fulfill order' }, 500);
  }
});

// POST mock shipping webhook
router.post('/webhooks/shipping', async (c) => {
  try {
    const body = await c.req.json();
    const { awbNumber, status } = body; // e.g., 'OUT_FOR_DELIVERY', 'DELIVERED'
    
    const shipment = await prisma.shipment.update({
      where: { awbNumber },
      data: { status }
    });

    // If delivered, update order status too
    if (status === 'DELIVERED') {
      await prisma.order.update({
        where: { id: shipment.orderId },
        data: { status: 'DELIVERED' }
      });
    }

    return c.json({ success: true });
  } catch (error) {
    return c.json({ error: 'Failed to process webhook' }, 500);
  }
});

export default router;
