import { Hono } from 'hono';
import { cors } from 'hono/cors';
import { secureHeaders } from 'hono/secure-headers';
import dotenv from 'dotenv';
import { PrismaD1 } from '@prisma/adapter-d1';
import { PrismaClient } from '@prisma/client';
import { asyncLocalStorage } from './lib/prisma';

import authRoutes from './routes/auth';
import productRoutes from './routes/products';
import categoryRoutes from './routes/categories';
import orderRoutes from './routes/orders';
import returnRoutes from './routes/returns';
import couponRoutes from './routes/coupons';
import postRoutes from './routes/posts';
import analyticsRoutes from './routes/analytics';
import uploadRoutes from './routes/upload';
import paymentRoutes from './routes/payments';
import shippingRoutes from './routes/shipping';
import auditLogsRoutes from './routes/auditLogs';
import inventoryRoutes from './routes/inventory';
import settingsRoutes from './routes/settings';

dotenv.config();

const app = new Hono<{ Bindings: { DB: any } }>();

app.use('*', secureHeaders());
app.use('*', cors());

app.use('*', async (c, next) => {
  console.log("c.env keys:", Object.keys(c.env || {}));
  console.log("c.env.DB:", c.env?.DB ? "Exists" : "Missing");
  if (c.env && c.env.DB) {
    const adapter = new PrismaD1(c.env.DB);
    const prisma = new PrismaClient({ adapter });
    return await asyncLocalStorage.run(prisma, async () => {
      await next();
    });
  }
  await next();
});


// Routes
app.route('/api/auth', authRoutes);
app.route('/api/products', productRoutes);
app.route('/api/categories', categoryRoutes);
app.route('/api/orders', orderRoutes);
app.route('/api/returns', returnRoutes);
app.route('/api/coupons', couponRoutes);
app.route('/api/posts', postRoutes);
app.route('/api/analytics', analyticsRoutes);
app.route('/api/upload', uploadRoutes);
app.route('/api/payments', paymentRoutes);
app.route('/api/shipping', shippingRoutes);
app.route('/api/audit-logs', auditLogsRoutes);
app.route('/api/inventory', inventoryRoutes);
app.route('/api/settings', settingsRoutes);

app.post('/api/seed', async (c) => {
  try {
    const prisma = asyncLocalStorage.getStore();
    if (!prisma) return c.json({ error: 'No prisma client' }, 500);

    // Delete existing products
    await prisma.product.deleteMany();
    await prisma.category.deleteMany();

    // Create 1 category and 5 products
    const category = await prisma.category.create({
      data: { name: 'Demo Category', slug: 'demo-category', description: 'Demo category' },
    });

    for (let i = 0; i < 5; i++) {
      await prisma.product.create({
        data: {
          name: `Demo Product ${i}`,
          slug: `demo-product-${i}`,
          shortDesc: `This is a demo product ${i}`,
          fullDesc: `Full description of demo product ${i}`,
          basePrice: 19.99,
          categoryId: category.id,
          published: true
        }
      });
    }

    return c.json({ success: true });
  } catch (err: any) {
    return c.json({ error: err.message }, 500);
  }
});

app.get('/health', (c) => {
  return c.json({ status: 'ok', timestamp: new Date().toISOString() });
});

export default app;
