import { Hono } from 'hono';
import multer from 'multer';
import { v2 as cloudinary } from 'cloudinary';
import { verifyToken, requireRoles } from '../middleware/auth';
import dotenv from 'dotenv';

dotenv.config();

const router = new Hono();

// Configure Cloudinary
cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME || 'dummy_cloud',
  api_key: process.env.CLOUDINARY_API_KEY || 'dummy_key',
  api_secret: process.env.CLOUDINARY_API_SECRET || 'dummy_secret'
});

// Configure Multer (store in memory for direct upload to Cloudinary)
const storage = multer.memoryStorage();
const upload = multer({ storage });

router.post('/', verifyToken, requireRoles(['SUPER_ADMIN', 'CATALOG_MANAGER', 'OPERATIONS']), upload.single('image'), async (c) => {
  try {
    if (!req.file) {
      return c.json({ error: 'No image file provided' }, 400);
    }

    // Convert buffer to base64 string for Cloudinary
    const b64 = Buffer.from(req.file.buffer).toString('base64');
    const dataURI = "data:" + req.file.mimetype + ";base64," + b64;
    
    const result = await cloudinary.uploader.upload(dataURI, {
      folder: 'crochet_store_products',
      resource_type: 'auto'
    });

    return c.json({ url: result.secure_url });
  } catch (error: any) {
    console.error('Upload Error:', error);
    return c.json({ error: 'Failed to upload image' }, 500);
  }
});

export default router;
