import { PrismaClient } from '@prisma/client';
import { PrismaD1 } from '@prisma/adapter-d1';
import { AsyncLocalStorage } from 'node:async_hooks';

export const asyncLocalStorage = new AsyncLocalStorage<PrismaClient>();

let fallbackClient: PrismaClient | null = null;

export const prisma = new Proxy({} as PrismaClient, {
  get(target, prop) {
    const client = asyncLocalStorage.getStore();
    if (client) {
      const val = client[prop as keyof PrismaClient];
      return typeof val === 'function' ? val.bind(client) : val;
    }
    
    // For local scripts outside Hono context (e.g. seed.ts)
    if (!fallbackClient) {
      // In cloudflare, this will crash, but in Node it's fine.
      fallbackClient = new PrismaClient();
    }
    const val2 = fallbackClient[prop as keyof PrismaClient];
    return typeof val2 === 'function' ? val2.bind(fallbackClient) : val2;
  }
});
