import { Hono } from 'hono';
import { verifyToken, requireRoles } from '../middleware/auth';

const router = new Hono();
import { prisma } from '../lib/prisma';

// POST Validate a coupon (Customer checkout)
router.post('/validate', async (c) => {
  try {
    const body = await c.req.json();
    const { code, orderValue } = body;
    
    const coupon = await prisma.coupon.findUnique({ where: { code } });
    
    if (!coupon) return c.json({ error: 'Coupon not found' }, 404);
    if (!coupon.isActive) return c.json({ error: 'Coupon is inactive' }, 400);
    if (coupon.validTo && new Date() > new Date(coupon.validTo)) return c.json({ error: 'Coupon has expired' }, 400);
    if (coupon.usageLimit && coupon.usedCount >= coupon.usageLimit) return c.json({ error: 'Coupon usage limit reached' }, 400);
    if (orderValue < coupon.minOrderValue) return c.json({ error: `Minimum order value is ₹${coupon.minOrderValue}` }, 400);
    
    // Calculate discount
    let discount = 0;
    if (coupon.type === 'PERCENTAGE') {
      discount = (orderValue * coupon.value) / 100;
    } else {
      discount = coupon.value;
    }
    
    return c.json({ valid: true, discount, coupon: { id: coupon.id, code: coupon.code } });
  } catch (error: any) {
    return c.json({ error: error.message }, 500);
  }
});

// Admin Routes Below
// ------------------

// GET all coupons
router.get('/', verifyToken, requireRoles(['SUPER_ADMIN', 'MARKETING']), async (c) => {
  try {
    const coupons = await prisma.coupon.findMany({ orderBy: { createdAt: 'desc' } });
    return c.json(coupons);
  } catch (error) {
    return c.json({ error: 'Failed to fetch coupons' }, 500);
  }
});

// POST Create coupon
router.post('/', verifyToken, requireRoles(['SUPER_ADMIN', 'MARKETING']), async (c) => {
  try {
    const data = req.body;
    const coupon = await prisma.coupon.create({ data });
    return c.json(coupon, 201);
  } catch (error: any) {
    return c.json({ error: error.message }, 400);
  }
});

// PUT Toggle active status
router.put('/:id/toggle', verifyToken, requireRoles(['SUPER_ADMIN', 'MARKETING']), async (c) => {
  try {
    const { id } = c.req.param();
    const coupon = await prisma.coupon.findUnique({ where: { id } });
    if (!coupon) return c.json({ error: 'Coupon not found' }, 404);
    
    const updated = await prisma.coupon.update({
      where: { id },
      data: { isActive: !coupon.isActive }
    });
    return c.json(updated);
  } catch (error) {
    return c.json({ error: 'Failed to update coupon' }, 500);
  }
});

export default router;
