import { Hono } from 'hono';
import { verifyToken, requireRoles } from '../middleware/auth';

const router = new Hono();
import { prisma } from '../lib/prisma';

// GET all store settings
router.get('/', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS']), async (c) => {
  try {
    const settings = await prisma.storeSettings.findMany();
    // Convert array of key-value objects to a single object map
    const settingsMap = settings.reduce((acc, curr) => {
      acc[curr.key] = curr.value;
      return acc;
    }, {} as Record<string, string>);
    
    return c.json(settingsMap);
  } catch (error) {
    return c.json({ error: 'Failed to fetch store settings' }, 500);
  }
});

// PUT update store settings (bulk)
router.put('/', verifyToken, requireRoles(['SUPER_ADMIN']), async (c) => {
  try {
    const updates = req.body; // Expects a map of key-value pairs
    
    await prisma.$transaction(
      Object.entries(updates).map(([key, value]) =>
        prisma.storeSettings.upsert({
          where: { key },
          update: { value: String(value) },
          create: { key, value: String(value) }
        })
      )
    );

    return c.json({ success: true });
  } catch (error) {
    return c.json({ error: 'Failed to update store settings' }, 500);
  }
});

export default router;
