import { Hono } from 'hono';
import { verifyToken, requireRoles } from '../middleware/auth';

const router = new Hono();
import { prisma } from '../lib/prisma';

// GET all published posts (Public)
router.get('/', async (c) => {
  try {
    const posts = await prisma.post.findMany({
      where: { published: true },
      orderBy: { createdAt: 'desc' },
      select: {
        id: true,
        title: true,
        slug: true,
        createdAt: true,
        author: { select: { name: true } }
      } // Exclude heavy content for list view
    });
    return c.json(posts);
  } catch (error) {
    return c.json({ error: 'Failed to fetch posts' }, 500);
  }
});

// GET single post by slug (Public)
router.get('/:slug', async (c) => {
  try {
    const { slug } = c.req.param();
    const post = await prisma.post.findUnique({
      where: { slug },
      include: { author: { select: { name: true } } }
    });
    
    if (!post) return c.json({ error: 'Post not found' }, 404);
    if (!post.published) return c.json({ error: 'Post is not published' }, 403);
    
    return c.json(post);
  } catch (error) {
    return c.json({ error: 'Failed to fetch post' }, 500);
  }
});

// Admin Routes Below
// ------------------

// GET all posts including unpublished (Admin)
router.get('/admin/all', verifyToken, requireRoles(['SUPER_ADMIN', 'MARKETING']), async (c) => {
  try {
    const posts = await prisma.post.findMany({
      orderBy: { createdAt: 'desc' },
      include: { author: { select: { name: true } } }
    });
    return c.json(posts);
  } catch (error) {
    return c.json({ error: 'Failed to fetch posts' }, 500);
  }
});

// POST Create new post (Admin)
router.post('/', verifyToken, requireRoles(['SUPER_ADMIN', 'MARKETING']), async (c) => {
  try {
    const body = await c.req.json();
    const { title, slug, content, published, authorId } = body;
    
    const post = await prisma.post.create({
      data: { title, slug, content, published, authorId }
    });
    
    return c.json(post, 201);
  } catch (error: any) {
    return c.json({ error: error.message }, 400);
  }
});

export default router;
