import { Hono } from 'hono';
import { verifyToken, requireRoles } from '../middleware/auth';

const router = new Hono();
import { prisma } from '../lib/prisma';

// GET inventory logs for a variant
router.get('/:variantId/logs', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'CATALOG_MANAGER']), async (c) => {
  try {
    const { variantId } = c.req.param();
    const logs = await prisma.inventoryLog.findMany({
      where: { variantId },
      include: { user: { select: { name: true } } },
      orderBy: { createdAt: 'desc' }
    });
    return c.json(logs);
  } catch (error) {
    return c.json({ error: 'Failed to fetch inventory logs' }, 500);
  }
});

// POST adjust inventory
router.post('/adjust', verifyToken, requireRoles(['SUPER_ADMIN', 'OPERATIONS', 'CATALOG_MANAGER']), async (c) => {
  try {
    const body = await c.req.json();
    const { variantId, changeAmount, reason } = body;
    
    if (changeAmount === 0) return c.json({ error: 'Change amount cannot be 0' }, 400);
    if (!['RESTOCK', 'MANUAL', 'ORDER', 'RETURN'].includes(reason)) {
      return c.json({ error: 'Invalid reason code' }, 400);
    }

    const result = await prisma.$transaction(async (tx) => {
      const variant = await tx.variant.update({
        where: { id: variantId },
        data: {
          stock: { increment: changeAmount }
        }
      });

      const log = await tx.inventoryLog.create({
        data: {
          variantId,
          changeAmount,
          reason,
          userId: c.get('user').userId
        }
      });

      return { variant, log };
    });

    return c.json(result);
  } catch (error) {
    return c.json({ error: 'Failed to adjust inventory' }, 500);
  }
});

export default router;
